	}
	if !strings.Contains(msg.TextBody, "reset your password") {
		t.Error("the reset mail must explain the action")
	}
	if !strings.Contains(msg.TextBody, "2 minute(s)") {
		t.Error("the TTL must be rendered in minutes")
	}
}

